## The Corrected Code

*With a wave of my hand, I'll mend what mortals have unmade!*

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    loaded    chan struct{} // signals when loading completes
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Check with read lock first
    c.mu.RLock()
    entry, ok := c.data[key]
    if ok && entry.loaded != nil {
        // Entry exists, check if loaded
        select {
        case <-entry.loaded:
            // Loaded, check expiry
            if time.Now().Before(entry.ExpiresAt) {
                c.mu.RUnlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
        default:
            // Still loading, wait for it
            c.mu.RUnlock()
            return c.waitForLoad(ctx, entry, key)
        }
    }
    c.mu.RUnlock()

    // Upgrade to write lock
    c.mu.Lock()
    // Double-check after acquiring write lock
    entry, ok = c.data[key]
    if ok && entry.loaded != nil {
        select {
        case <-entry.loaded:
            if time.Now().Before(entry.ExpiresAt) {
                c.mu.Unlock()
                atomic.AddInt64(&c.stats.Hits, 1)
                return entry.Value, nil
            }
        default:
            c.mu.Unlock()
            return c.waitForLoad(ctx, entry, key)
        }
    }

    // We're the loader - create entry with channel
    entry = &CacheEntry{loaded: make(chan struct{})}
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    value, err := c.loader(ctx, key)
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        c.mu.Lock()
        delete(c.data, key)
        c.mu.Unlock()
        close(entry.loaded) // Signal waiters
        return nil, err
    }

    c.mu.Lock()
    entry.Value = value
    entry.ExpiresAt = time.Now().Add(c.ttl)
    c.mu.Unlock()
    close(entry.loaded) // Signal waiters

    return value, nil
}

func (c *Cache) waitForLoad(ctx context.Context, entry *CacheEntry, key string) (interface{}, error) {
    select {
    case <-ctx.Done():
        return nil, ctx.Err()
    case <-entry.loaded:
        c.mu.RLock()
        defer c.mu.RUnlock()
        current, ok := c.data[key]
        if !ok || current != entry {
            return nil, ctx.Err() // Entry was replaced/deleted
        }
        return entry.Value, nil
    }
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    loaded := make(chan struct{})
    close(loaded)
    c.data[key] = &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        loaded:    loaded,
    }
}

func (c *Cache) Invalidate(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.data, key)
}

func (c *Cache) InvalidateAll() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data = make(map[string]*CacheEntry)
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanupLoop() {
    ticker := time.NewTicker(time.Minute)
    defer ticker.Stop()
    for range ticker.C {
        c.cleanup()
    }
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()
    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.loaded:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't delete
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}
```

---

## Key Fixes Summary

| Issue | Fix |
|-------|-----|
| Concurrent map access | `sync.RWMutex` everywhere |
| Stats races | `atomic.AddInt64` |
| Cache stampede | Channel-based signaling (`loaded chan`) |
| GetMulti races | `sync.WaitGroup` + local mutex |
| Stale reads | Proper lock ordering, channel waits |

*If these shadows have offended, think but this and all is mended!* The cache now dances to a proper tune - no more fairy mischief causing panics in production. Lord, what fools these mortals be, writing concurrent code without proper synchronization! 🧚
